@Override public synchronized void recordMetric(MetricPoint point) {
    if (settled) return;
    var attributes = toAttributes(policy.sanitize(point.attributes()));
    switch (point.kind()) {
        case COUNTER -> {
            DoubleCounter counter = meter.counterBuilder(point.name()).ofDoubles().build();
            counter.add(point.value(), attributes);
        }
        case HISTOGRAM -> {
            DoubleHistogram histogram = meter.histogramBuilder(point.name()).build();
            histogram.record(point.value(), attributes);
        }
    }
}
